import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        // binary carry: each stack keeps its parity, half of the rest moves up
        long carry = 0, answer = 0;
        for (int i = 0; i < n; i++) {
            carry += nextLong();
            answer += carry % 2;
            carry /= 2;
        }
        System.out.println(answer + Long.bitCount(carry));
    }
}

package main

import (
	"fmt"
	"io"
	"math/bits"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// binary carry: each stack keeps its parity, half of the rest moves up
	var carry, answer int64
	for i := 0; i < n; i++ {
		carry += nextInt()
		answer += carry % 2
		carry /= 2
	}
	fmt.Println(answer + int64(bits.OnesCount64(uint64(carry))))
}
